// v2: 使用 ITriggerOrActionListPageParams 替代 IActionOrTriggerListPageParams
import { ITriggerOrActionListPageParams, TriggerOrActionListTypeEnum } from "@droid/project-v2-interface";
import { ActionGroupContext, ActionListContext, getActionGroupElement, IActionGroup, TriggerActionContext, TriggerActionGroupContext } from "@droid/project-v2-interface";
import { Log, toProxy, useProxyWatch, useTranslation } from "@fanfanlo";
import { Box, FormControlLabel, FormGroup, Grid2, Switch } from "@mui/material";
import { useContext } from "react";
import { GroupCheck } from "../../../components/group/GroupCheck";
import { ActionListOrTriggerListPageLink } from "../../../components/list-page-link/ActionListOrTriggerListPageLink";
import { ProjectCategoryUIConfigContext, ProjectEditInfoContext } from "../../../contexts";
import { ActionList } from "./action-list/ActionList";

const fileLog = new Log(true, 'ActionGroup_f');
fileLog.pause = true;
fileLog.childrenPaused = true;

export function ActionGroup({ actionGroup }: { actionGroup: IActionGroup }) {
    const {t} = useTranslation("droid-project-v2-ui/ui/project/edit-project/trigger-action-group/trigger-action/action-group/content")
    const editInfo = useContext(ProjectEditInfoContext)
    const triggerActionGroup = useContext(TriggerActionGroupContext)
    const triggerAction = useContext(TriggerActionContext)
    const uiConfig = useContext(ProjectCategoryUIConfigContext)

    fileLog.log(`[ActionGroup] uiConfig.showActionList=${uiConfig.showActionList}`)

    // v2: 使用 ITriggerOrActionListPageParams 和 Ulid 后缀的参数名
    const query: ITriggerOrActionListPageParams = {
        projectUlid: editInfo.project.ulid,
        triggerActionGroupUlid: triggerActionGroup.ulid,
        triggerActionUlid: triggerAction.ulid,
        actionGroupUlid: actionGroup.ulid,
        type: TriggerOrActionListTypeEnum.addAction,
        actionType: '',
    }
    const [isSequential] = useProxyWatch(actionGroup, 'isSequential', actionGroup.isSequential)
    // 修改：改为监听children而不是list（web端主要使用children）
    const [listSize] = useProxyWatch(actionGroup, 'children.length', actionGroup.children?.length ?? 0)
    function setIsSequential(value: boolean) {
        toProxy(actionGroup).isSequential = value
    }
    // 使用 children 而不是 list，因为 children 存储完整对象
    const childrenArray = actionGroup.children || [];
    return (
        <ActionGroupContext.Provider value={actionGroup}>
            <ActionListContext.Provider value={childrenArray}>

                <Box sx={{ border: '2px solid #ccc', padding: '4px' }}>
                    <Grid2 container sx={{ alignItems: 'center' }}>
                        <Grid2 size={"grow"}>
                            <Box>{t("content.title")}</Box>
                        </Grid2>
                        <Grid2>
                            {listSize > 1 && <FormGroup>
                                <FormControlLabel control={<Switch checked={isSequential}
                                data-id="action-group-checkbox-is-sequential.122f"
                                aria-checked={isSequential}
                                data-checked={isSequential}
                                onChange={(e) => { setIsSequential(e.target.checked) }} />} label={t("content.sequential")} />
                            </FormGroup>}
                        </Grid2>
                        {/* 根据 showActionList 决定是否显示 action 列表按钮 */}
                        {uiConfig.showActionList && (
                            <Grid2>
                                <Box>
                                    <ActionListOrTriggerListPageLink query={query} attrs={getActionGroupElement(actionGroup)} path="/action-list" btnId="link-router-to-action-list" testId="ActionGroup__actionListLink__01JFXYZB2C3D4E5F6G7H8I9" children={t("content.list")} />
                                </Box>
                            </Grid2>
                        )}
                    </Grid2>
                    <GroupCheck group={actionGroup} />
                    <ActionList />
                </Box>
            </ActionListContext.Provider>
        </ActionGroupContext.Provider>
    )
}
